class Solution:
    def calculateScore(self, s: str) -> int:
        n = len(s)
        # Map each character to its mirror in the alphabet
        mirror = {chr(ord('a') + i): chr(ord('a') - i - 1) for i in range(26)}

        # Keep track of marked indices
        marked = [False] * n
        total_score = 0

        for i in range(n):
            if marked[i]:
                continue

            # Find the closest unmarked index j < i such that s[j] is the mirror of s[i]
            j = i - 1
            while j >= 0:
                if not marked[j]:
                    if mirror[s[j]] == s[i]:
                        total_score += i - j
                        marked[i] = True
                        marked[j] = True
                        break
                j -= 1

        return total_score
