class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7

        m, n = len(grid), len(grid[0])

        # dp[i][j] = (count, xor_sum)
        # We use two rows to save space
        dp = [[(0, 0) for _ in range(n)] for _ in range(m)]

        def dfs(i, j, current_xor):
            if i == m - 1 and j == n - 1:
                if current_xor == k:
                    return 1
                return 0

            total = 0

            # Move right
            if j + 1 < n:
                nxt_j = j + 1
                val = grid[i][nxt_j]
                new_xor = current_xor ^ val
                if new_xor == k:
                    total = (total + dfs(i, nxt_j, new_xor)) % MOD
            # Move down
            if i + 1 < m:
                nxt_i = i + 1
                val = grid[nxt_i][j]
                new_xor = current_xor ^ val
                if new_xor == k:
                    total = (total + dfs(nxt_i, j, new_xor)) % MOD

            dp[i][j] = [(total % MOD, current_xor)]
            return 0

        # Since the constraints are small (m, n <= 300) and values are small (0-15),
        # we can use a memoized DFS. However, a direct DFS without memoization might TLE
        # because the state space is 2^(m+n) in the worst case without pruning.
        # Instead, we use dynamic programming with a map to store results for each (i, j, xor_sum).

        memo = {}

        def dfs_dp(i, j, current_xor):
            state = (i, j, current_xor)
            if state in memo:
                return memo[state]

            if i == m - 1 and j == n - 1:
                if current_xor == k:
                    res = 1
                else:
                    res = 0
            else:
                res = 0
                if j + 1 < n:
                    val = grid[i][j + 1]
                    new_xor = current_xor ^ val
                    res = (res + dfs_dp(i, j + 1, new_xor)) % MOD
                if i + 1 < m:
                    val = grid[i + 1][j]
                    new_xor = current_xor ^ val
                    res = (res + dfs_dp(i + 1, j, new_xor)) % MOD

            memo[state] = res
            return res

        return dfs_dp(0, 0, 0)
