    def maxRectangleArea(self, points: List[List[int]]) -> int:
        n = len(points)
        if n < 4:
            return -1

        # Group points by x-coordinate
        x_to_points = {}
        for i, p in enumerate(points):
            x = p[0]
            if x not in x_to_points:
                x_to_points[x] = []
            x_to_points[x].append((p[1], i))

        # Group points by y-coordinate
        y_to_points = {}
        for i, p in enumerate(points):
            y = p[1]
            if y not in y_to_points:
                y_to_points[y] = []
            y_to_points[y].append((p[0], i))

        # Identify candidate rectangles by pairs of x and y
        candidates = []

        for x in x_to_points:
            x_points = x_to_points[x]
            for i in range(len(x_points)):
                for j in range(i + 1, len(x_points)):
                    p1 = x_points[i][0]
                    p2 = x_points[j][0]
                    for y in y_to_points:
                        y_points = y_to_points[y]
                        for k in range(len(y_points)):
                            for l in range(k + 1, len(y_points)):
                                q1 = y_points[k][0]
                                q2 = y_points[l][0]

                                # Check if this rectangle is valid (no points inside or on border)
                                area = abs(p1 - p2) * abs(q1 - q2)
                                if area == 0:
                                    continue

                                # Collect all points in this rectangle
                                rect_points = set()
                                rect_points.add((p1, q1))
                                rect_points.add((p1, q2))
                                rect_points.add((p2, q1))
                                rect_points.add((p2, q2))

                                # Check for any other point inside or on the border
                                valid = True
                                for p in points:
                                    px, py = p
                                    if px == p1 and py == q1:
                                        continue
                                    if px == p1 and py == q2:
