class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        # Use a map to store the count of each product value seen so far
        product_counts = defaultdict(int)
        product_counts[1] = 1  # empty prefix has product 1 with count 1

        ans = 0

        for i in range(n - 3):
            # Check all possible (p, q, r, s) where p = i, q = i+1, r = i+2, s = i+3
            for p in range(i, n - 2):
                for q in range(p + 2, n - 1):
                    for r in range(q + 2, n - 2):
                        for s in range(r + 2, n):
                            prod = nums[p] * nums[r]
                            if product_counts.get(prod, 0) > 0:
                                ans += product_counts[prod]

        return ans
