from functools import lru_cache

class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        INF = float('inf')

        @lru_cache(None)
        def dp(idx: int, energy: int, x: int) -> int:
            """
            idx: current lock index to break (0..n-1)
            energy: current energy of the sword
            x: current factor of energy increase (1 + number of locks already broken)
            Returns: minimum time (in minutes) to break locks[idx:] given current state
            """
            if idx == n:
                return 0

            # Try breaking each lock from idx
            for energy_needed in range(strength[idx]):
                if energy >= energy_needed:
                    # Time to break this lock + remaining time
                    time = 1 + dp(idx + 1, 0, x + 1)
                    return min(time, INF)

            return INF

