from typing import List

class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7

        m, n = len(grid), len(grid[0])
        # dp[i][j][x] = number of paths from (0,0) to (i,j) with XOR sum x
        # Since k < 16 and grid values < 16, the XOR sum will always be < 32.
        # We can optimize space by only keeping the previous row.
        dp = [[[0] * 32 for _ in range(n)] for _ in range(m)]

        # Base case: start cell
        dp[0][0][grid[0][0]] += 1

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                current_xor = grid[i][j]
                for x in range(32):
                    if dp[i-1][j][x]:
                        new_x = x ^ current_xor
                        if new_x < 32:
                            dp[i][j][new_x] = (dp[i][j][new_x] + dp[i-1][j][x]) % MOD

                if j == 0:
                    continue

                for x in range(32):
                    if dp[i][j-1][x]:
                        new_x = x ^ current_xor
                        if new_x < 32:
                            dp[i][j][new_x] = (dp[i][j][new_x] + dp[i][j-1][x]) % MOD

        return dp[m-1][n-1][k]
