class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        if len(points) < 4:
            return -1

        # Group points by x-coordinate to find min and max y for each x
        x_to_xs = {}
        for x, y in points:
            if x not in x_to_xs:
                x_to_xs[x] = []
            x_to_xs[x].append(y)

        # Find valid ranges for each x (min_y, max_y)
        # A rectangle is valid if both x and y have at least 2 points in their ranges
        # and no other point lies inside or on the border.

        # First, check if we have any x with at least 2 points
        valid_xs = [x for x, ys in x_to_xs.items() if len(ys) >= 2]

        if not valid_xs:
            return -1

        # Collect all unique y coordinates across all x
        all_ys = set()
        for ys in x_to_xs.values():
            all_ys.update(ys)

        # For each valid x, determine the range of y that allows a rectangle
        # We need to check if the rectangle formed by two valid x's and two valid y's
        # is valid (no internal points).

        # To avoid O(N^4), we can iterate over pairs of valid x's and valid y's
        # and check the condition efficiently.

        max_area = 0

        # For each pair of valid x's
        for i in range(len(valid_xs)):
            x1 = valid_xs[i]
            # For each pair of valid y's (y1, y2)
            for j in range(i + 1, len(valid_xs)):
                x2 = valid_xs[j]

                # For each pair of valid y's
                for k in range(len(valid_ys)):
                    y1 = all_ys[k]
                    for l in range(k + 1, len(all_ys)):
                        y2 = all_ys[l]

                        # Check if the rectangle with corners (x1,y1), (x1,y2), (x2,y1), (x2,y2)
                        # is valid: no other point lies inside or on the border.

                        # Collect all points that lie on the border or inside
                        border_points = []
                        border_points.append((x1, y1))
                        border_points.append((x1, y2))
                        border_points.append((x2, y1))
                        border_points.append((x2, y2))

                        # Check points on the border
                        for p in points:
                            if p == (x1, y1) or p == (x1, y2) or p == (x2, y1) or p == (x2, y2):
                                continue
                            # Check if point is on the line segment between corners
                            # For each edge, check if the point is collinear and within bounds
                            # Since points are unique and grid-like, we can check collinearity
                            # and inclusion.

                            # Edge from (x1,y1) to (x1,y2)
                            if p[0] == x1 and (y1 == y2 or abs(p[1] - y1) <= 1):
                                # Check if p is on the segment (inclusive)
                                if y1 <= p[1] <= y2:
                                    continue
                                # Check if p is strictly between (y1, x1) and (y2, x1)
                                if y1 < p[1] < y2:
                                    continue
                            # Edge from (x1,y1) to (x2,y1)
                            if p[1] == y1 and (x1 == x2 or abs(p[0] - x1) <= 1):
                                if x1 <= p[0] <= x2:
                                    continue
                                if x1 < p[0] < x2:
                                    continue
                            # Edge from (x1,y2) to (x2,y2)
                            if p[1] == y2 and (x1 == x2 or abs(p[0] - x1) <= 1):
                                if x1 <= p[0] <= x2:
                                    continue
                                if x1 < p[0] < x2:
                                    continue
                            # Edge from (x2,y1) to (x2,y2)
                            if p[1] == y1 and (x2 == x2 or abs(p[0] - x2) <= 1):
                                if x2 <= p[0] <= x2:
                                    continue
                                if x2 < p[0] < x2:
                                    continue

                                # Check if point is inside the rectangle
                                if x1 < p[0] < x2 and y1 < p[1] < y2:
                                    continue

                                # This point is on the border or inside, so invalid
                                break
                        else:
                            # No invalid points found, calculate area
                            area = (x2 - x1) * (y2 - y1)
                            if area > max_area:
                                max_area = area
