from typing import List

class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        # Use a set to store seen numbers at each index (to avoid duplicates)
        seen = [set() for _ in range(n)]

        # seen[i] will store the set of numbers at indices i-1, i-2, ..., 0
        # that have been processed so far and satisfy the condition.
        for i in range(n - 1, -1, -1):
            current_num = nums[i]
            # For each previous index j, check if there exists an index k > i
            # such that nums[k] = current_num and nums[k] * nums[j] = current_num * nums[k]
            # This simplifies to nums[j] == nums[k]
            # So we only need to check if any value in seen[i+1:] equals current_num.
            for j in range(i + 1, n):
                if seen[j] and current_num in seen[j]:
                    seen[i].add(current_num)
            seen[i].add(current_num)

        total = 0
        for i in range(n):
            for j in seen[i]:
                if j in seen[i+1]:
                    total += 1
        return total
